"""Metadata, column helpers and mixins shared by every table."""

import datetime
import enum

import sqlalchemy as sa
import sqlmodel

# Deterministic constraint names, so autogenerated migrations can drop them.
sqlmodel.SQLModel.metadata.naming_convention = {
    'ix': 'ix_%(column_0_label)s',
    'uq': 'uq_%(table_name)s_%(column_0_N_name)s',
    'ck': 'ck_%(table_name)s_%(constraint_name)s',
    'fk': 'fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s',
    'pk': 'pk_%(table_name)s',
}

METADATA = sqlmodel.SQLModel.metadata


def pg_enum(enum_class: type[enum.Enum], name: str) -> sa.Enum:
    """Returns a native PostgreSQL enum that stores the members' values.

    Args:
        enum_class: Python enum whose values become the type's labels.
        name: Name of the PostgreSQL type.
    """
    return sa.Enum(
        enum_class,
        name=name,
        values_callable=lambda members: [member.value for member in members],
    )


def utc_now() -> datetime.datetime:
    """Returns the current time, timezone-aware, in UTC."""
    return datetime.datetime.now(datetime.UTC)


class CreatedAtMixin(sqlmodel.SQLModel):
    """Adds the time a row was inserted."""

    created_at: datetime.datetime = sqlmodel.Field(
        default_factory=utc_now,
        sa_type=sa.DateTime(timezone=True),
        sa_column_kwargs={'server_default': sa.func.now()},
    )


class TimestampMixin(CreatedAtMixin):
    """Adds the times a row was inserted and last changed."""

    updated_at: datetime.datetime = sqlmodel.Field(
        default_factory=utc_now,
        sa_type=sa.DateTime(timezone=True),
        sa_column_kwargs={'server_default': sa.func.now(), 'onupdate': utc_now},
    )
